const sessionByHash = `-- name: SessionByHash :one
SELECT s.id, s.user_id, s.mfa_auth_time, s.last_seen_at, s.idle_expires_at,
       s.absolute_expires_at, s.revoked_at, s.provider_session_id,
       (u.disabled_at IS NOT NULL)::boolean AS user_disabled
FROM sessions s
JOIN users u ON u.id = s.user_id
WHERE s.token_hash = $1
`

type SessionByHashRow struct {
	ID                pgtype.UUID
	UserID            pgtype.UUID
	MfaAuthTime       pgtype.Timestamptz
	LastSeenAt        pgtype.Timestamptz
	IdleExpiresAt     pgtype.Timestamptz
	AbsoluteExpiresAt pgtype.Timestamptz
	RevokedAt         pgtype.Timestamptz
	ProviderSessionID pgtype.Text
	UserDisabled      bool
}

func (q *Queries) SessionByHash(ctx context.Context, tokenHash []byte) (SessionByHashRow, error) {
	row := q.db.QueryRow(ctx, sessionByHash, tokenHash)
	var i SessionByHashRow
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.MfaAuthTime,
		&i.LastSeenAt,
		&i.IdleExpiresAt,
		&i.AbsoluteExpiresAt,
		&i.RevokedAt,
		&i.ProviderSessionID,
		&i.UserDisabled,
	)
	return i, err
}

